/* @autogenerated */
import { Component, inject } from '@angular/core';
import { SnippetAsset } from 'app/features/template/snippet-asset/model/snippet-asset.model';
import { SnippetAssetRepository } from 'app/features/template/snippet-asset/repository/snippet-asset-repository.service';
import { ConfirmSelectionAction } from 'app/shared/toolkit/action/confirm-selection-action';

@Component({ selector: 'snippet-asset-view-enable-selection-action', standalone: false, template: '' })
export class SnippetAssetViewEnableSelectionActionComponent extends ConfirmSelectionAction<SnippetAsset> {
  readonly name = 'enableSelection';
  protected readonly scope = 'template/snippet-asset';
  protected readonly repository = inject(SnippetAssetRepository);

  protected override appliesTo(items: SnippetAsset[]) {
    return items.every((item) => item.enabled !== true);
  }

  protected runSelection(items: SnippetAsset[]) {
    return this.repository.enableSelection({ uids: items.map((item) => item.uid) });
  }
}
